DELIMITER $$
CREATE TRIGGER tr_sc_ins BEFORE INSERT ON sc
FOR EACH ROW
BEGIN
  IF NEW.grade < 0 THEN SET NEW.grade = 0;
  ELSEIF NEW.grade > 100 THEN
    SET NEW.grade = 100;
  END IF;
END $$
CREATE TRIGGER tr_sc_upd BEFORE UPDATE ON sc
FOR EACH ROW
BEGIN
  IF NEW.grade < 0 THEN SET NEW.grade = 0;
  ELSEIF NEW.grade > 100 THEN
    SET NEW.grade = 100;
  END IF;
END $$
DELIMITER ;
