CREATE TABLE sal_log (
  id      INT AUTO_INCREMENT PRIMARY KEY,
  eno     CHAR(4),
  old_sal DECIMAL(8,2),
  new_sal DECIMAL(8,2),
  op_time DATETIME
);
DELIMITER $$
CREATE TRIGGER tr_sal AFTER UPDATE ON emp
FOR EACH ROW
BEGIN
  IF NEW.salary <> OLD.salary THEN
    INSERT INTO sal_log(eno, old_sal,
      new_sal, op_time)
    VALUES (OLD.eno, OLD.salary,
      NEW.salary, NOW());
  END IF;
END $$
DELIMITER ;
CREATE TRIGGER tr_emp_del AFTER DELETE ON emp
FOR EACH ROW
  INSERT INTO sal_log(eno, old_sal, op_time)
  VALUES (OLD.eno, OLD.salary, NOW());
UPDATE emp SET salary = salary + 500
  WHERE eno = 'E001';
DELETE FROM emp WHERE eno = 'E002';
SELECT * FROM sal_log;
